-- Catálogo de barrios — igual patrón que ciudades: no hay fuente oficial única de barrios en
-- Colombia (a diferencia de departamentos y municipios, que sí tienen código DANE), así que en vez
-- de intentar cargar una lista completa, la tabla crece sola: quien escribe un barrio que no
-- existe lo crea "pendiente de confirmar", y un admin lo revisa/depura después (ver
-- CiudadService.crear, mismo criterio).
CREATE TABLE "barrios" (
  "id_barrio" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "nombre" VARCHAR(150) NOT NULL,
  "id_ciudad" INTEGER NOT NULL REFERENCES "ciudades"("id_ciudad"),
  "pendiente_confirmacion" BOOLEAN NOT NULL DEFAULT true
);

CREATE INDEX ON "barrios" ("id_ciudad");
